ors.append(f\\\"Codebook values not mapped (data has them, codebook documents them): {documented_unmapped}\\\")\\n    if undocumented_unmapped:\\n        warnings.append(f\\\"Undocumented codes in data (not in codebook, becoming NaN): {undocumented_unmapped}\\\")\\n    if not documented_unmapped and not undocumented_unmapped:\\n        print(f\\\"[OK] All codebook values are mapped\\\")\\n\\n# --- VERDICT ---\\nprint(\\\"\\\")\\nprint(\\\"=\\\"*60)\\nif errors:\\n    print(\\\"VERDICT: needs_fix\\\")\\n    for e in errors:\\n        print(f\\\"  [ERROR] {e}\\\")\\n    for w in warnings:\\n        print(f\\\"  [WARN]  {w}\\\")\\n    sys.exit(1)\\nelif warnings:\\n    print(\\\"VERDICT: ok (with warnings)\\\")\\n    for w in warnings:\\n        print(f\\\"  [WARN]  {w}\\\")\\nelse:\\n    print(\\\"VERDICT: ok\\\")\\nprint(\\\"=\\\"*60)\\nEOF\\n\\\\`\\\\`\\\\`\"\n            },\n            \"error\": \"ProviderModelNotFoundError: ProviderModelNotFoundError\",\n            \"time\": {\n              \"start\": 1773452529747,\n              \"end\": 1773452529749\n            }\n          },\n          \"id\": \"prt_cea021050001wLzs3oN0cBEtE2\",\n          \"sessionID\": \"ses_315fe039affen5r12Wgz4YhH4z\",\n          \"messageID\": \"msg_cea01fd0f001nB6681ciFwlvKj\"\n        },\n        {\n          \"type\": \"step-finish\",\n          \"reason\": \"tool-calls\",\n          \"snapshot\": \"ba6a76f9d8861d23f7282fdf55bef9a7a83899d4\",\n          \"cost\": 0.00157295,\n          \"tokens\": {\n            \"total\": 15050,\n            \"input\": 806,\n            \"output\": 3030,\n            \"reasoning\": 0,\n            \"cache\": {\n              \"read\": 11214,\n              \"write\": 0\n            }\n          },\n          \"id\": \"prt_cea02105b0016aUQ1kRCUJGBbu\",\n          \"sessionID\": \"ses_315fe039affen5r12Wgz4YhH4z\",\n          \"messageID\": \"msg_cea01fd0f001nB6681ciFwlvKj\"\n        }\n      ]\n    },\n    {\n      \"info\": {\n        \"role\": 