\\\"q12\\\",\\n  \\\"data_file\\\": \\\"_SharedFolder_data_produit/eeq_2007/Quebec Election Study 2007 (SPSS).sav\\\",\\n  \\\"codebook_entry\\\": {\\n    \\\"raw_name\\\": \\\"q12\\\",\\n    \\\"label\\\": \\\"Confiance dans le gouvernement provincial\\\",\\n    \\\"type\\\": \\\"likert\\\",\\n    \\\"values\\\": {\\\"1\\\": \\\"beaucoup\\\", \\\"2\\\": \\\"assez\\\", \\\"3\\\": \\\"pas tellement\\\", \\\"4\\\": \\\"pas du tout\\\"},\\n    \\\"missing_codes\\\": [8, 9]\\n  }\\n}\\n\\nThe var file path is derived automatically: `surveys/{survey_id}/vars/{variable_name}.py`\\n\\n### Step 1: Read the var file\\n\\nThe var file path is `surveys/{survey_id}/vars/{variable_name}.py`. Read it to extract:\\n1. The `raw_name` (source column — from the `# Source: ...` comment or from `df['...']`)\\n2. The `standard_name` (cleaned column — from `df_clean['...']`)\\n3. The mapping dict (from the `.map({...})` call)\\n\\n### Step 2: Load only the raw column and execute the mapping\\n\\nRun as a single bash heredoc (no temp file). Pass `codebook_entry.values` via an env variable to avoid quoting issues with accented characters:\\n\\n\\\\`\\\\`\\\\`bash\\nCODEBOOK_VALUES_JSON='{\\\"1\\\": \\\"beaucoup\\\", \\\"2\\\": \\\"assez\\\", \\\"3\\\": \\\"pas tellement\\\", \\\"4\\\": \\\"pas du tout\\\"}' \\\\\\nvenv/bin/python - <<'EOF'\\nimport sys\\nsys.path.insert(0, '.')\\nimport json\\nimport os\\nimport numpy as np\\nimport pandas as pd\\nfrom pathlib import Path\\nfrom surveys.io import read_survey_file\\n\\n# --- Fill in from context ---\\nRAW_NAME = \\\"q12\\\"\\nVAR_FILE = \\\"surveys/eeq_2007/vars/q12.py\\\"\\nCODEBOOK_VALUES = json.loads(os.environ.get(\\\"CODEBOOK_VALUES_JSON\\\", \\\"{}\\\"))  # codebook_entry.values\\n# --- DATA FILE PATH ---\\nDATA_FILE_PATH = Path(\\\"/_SharedFolder_data_produit/eeq_2007/Quebec Election Study 2007 (SPSS).sav\\\")\\n\\n# Load only the raw column\\ndf, _ = read_survey_file(DATA_FILE_PATH, usecols=[RAW_NAME])\\n\\nif RAW_NAME not in df.columns:\\n    df_all, _ = read_survey_file(DATA_FILE_PATH)\\n    print(f\\\"ERROR: '{RAW_NAME}' not found. Available: {list(df_all.columns[:20])}\\\")\\n    sys.exit(1)\\n\\nprint(f\\\"Loaded {len(df)} rows for column '{RAW_NAME}'\\\")\\nprint(f\\\"dtype: {df[RAW_NAME].dtype}\\\")\\nprint(f\\\"Raw value_counts (sorted):\\\")\\nprint(df[RAW_NAME].value_counts(dropna=False).sort_index().to_string())\\n\\n# Execute the mapping from the var file\\ndf_clean = pd.DataFrame(index=df.index)\\nCODEBOOK_VARIABLES = {}\\n\\nvar_code = open(VAR_FILE).read()\\nexec(var_code, {\\\"df\\\": df, \\\"df_clean\\\": df_clean, \\\"np\\\": np, \\\"CODEBOOK_VARIABLES\\\": CODEBOOK_VARIABLES})\\n\\n# Find the standard_name (first key written to df_clean)\\nstd_cols = list(df_clean.columns)\\nif not std_cols:\\n    print(\\\"ERROR: var file did not write any column to df_clean\\\")\\n    sys.exit(1)\\nSTANDARD_NAME = std_cols[0]\\nprint(\\\"Clean column: '\\\" + STANDARD_NAME + \\\"'\\\")\\nprint(\\\"Clean value_counts (sorted):\\\")\\nprint(df_clean[STANDARD_NAME].value_counts(dropna=False).sort_index().to_string())\\n\\n# --- VALIDATION CHECKS ---\\nprint(\\\"\\\")\\nprint(\\\"=\\\"*60)\\nprint(\\\"VALIDATION\\\")\\nprint(\\\"=\\\"*60)\\n\\nerrors = []\\nwarnings = []\\n\\n# Check 1: Row count\\nn_raw = len(df)\\nn_clean = len(df_clean)\\nif n_raw != n_clean:\\n    errors.append(f\\\"Row count mismatch: raw={n_raw} clean={n_clean}\\\")\\nelse:\\n    print(f\\\"[OK] Row count: {n_raw}\\\")\\n\\n# Check 2: Mapping coverage — values in data not covered by mapping\\nraw_vals = set(df[RAW_NAME].dropna().unique())\\n# Reconstruct keys used in the mapping from df_clean result\\n# We detect unmapped: non-NaN raw but NaN clean\\nunmapped_mask = df[RAW_NAME].notna() & df_clean[STANDARD_NAME].isna()\\nunmapped_vals = set(df.loc[unmapped_mask, RAW_NAME].unique())\\nif unmapped_vals:\\n    counts = {v: int((df[RAW_NAME] == v).sum()) for v in unmapped_vals}\\n    warnings.append(f\\\"Unmapped values (→ NaN): {counts}\\\")\\n    print(f\\\"[WARN] Unmapped values become NaN: {counts}\\\")\\nelse:\\n    print(f\\\"[OK] All non-missing raw values are mapped\\\")\\n\\n# Check 3: NaN rate\\nraw_nan_pct = df[RAW_NAME].isna().mean() * 100\\nclean_nan_pct = df_clean[STANDARD_NAME].isna().mean() * 100\\nnan_increase = clean_nan_pct - raw_nan_pct\\nif nan_increase > 20:\\n    errors.append(f\\\"NaN increased by {nan_increase:.1f}pp (raw {raw_nan_pct:.1f}% → clean {clean_nan_pct:.1f}%)\\\")\\nelif nan_increase > 5:\\n    warnings.append(f\\\"NaN increased by {nan_increase:.1f}pp (raw {raw_nan_pct:.1f}% → clean {clean_nan_pct:.1f}%)\\\")\\nelse:\\n    print(f\\\"[OK] NaN rate: raw={raw_nan_pct:.1f}% clean={clean_nan_pct:.1f}%\\\")\\n\\n# Check 4: All values became NaN (total failure)\\nif df_clean[STANDARD_NAME].notna().sum() == 0:\\n    errors.append(\\\"ALL values are NaN — mapping completely failed\\\")\\n\\n# Check 5: CODEBOOK_VARIABLES entry\\nif STANDARD_NAME not in CODEBOOK_VARIABLES:\\n    warnings.append(f\\\"CODEBOOK_VARIABLES['{STANDARD_NAME}'] not set\\\")\\nelse:\\n    cb = CODEBOOK_VARIABLES[STANDARD_NAME]\\n    for key in ['original_variable', 'question_label', 'type', 'value_labels']:\\n        if key not in cb:\\n            warnings.append(f\\\"CODEBOOK_VARIABLES['{STANDARD_NAME}'] missing key '{key}'\\\")\\n    print(f\\\"[OK] CODEBOOK_VARIABLES entry present\\\")\\n\\n# Check 6: Naming convention\\nimport re as _re\\nif not _re.match(r'^(ses|op|behav|know)_', STANDARD_NAME):\\n    warnings.append(f\\\"standard_name '{STANDARD_NAME}' does not follow ses_/op_/behav_/know_* convention\\\")\\nelse:\\n    print(f\\\"[OK] Naming convention: {STANDARD_NAME}\\\")\\n\\n# Check 7: value_labels keys match actual df_clean values\\nif STANDARD_NAME in CODEBOOK_VARIABLES:\\n    vl = CODEBOOK_VARIABLES[STANDARD_NAME].get('value_labels', {})\\n    actual_clean_vals = set(str(v) for v in df_clean[STANDARD_NAME].dropna().unique())\\n    vl_keys = set(str(k) for k in vl.keys())\\n    phantom_keys = vl_keys - actual_clean_vals\\n    missing_keys = actual_clean_vals - vl_keys\\n    if phantom_keys:\\n        warnings.append(f\\\"value_labels has phantom keys not in df_clean: {phantom_keys}\\\")\\n    if missing_keys:\\n        warnings.append(f\\\"value_labels missing keys present in df_clean: {missing_keys}\\\")\\n    if not phantom_keys and not missing_keys:\\n        print(f\\\"[OK] value_labels keys match df_clean values\\\")\\n\\n# Check 8: type consistency vs actual clean values\\nif STANDARD_NAME in CODEBOOK_VARIABLES:\\n    declared_type = CODEBOOK_VARIABLES[STANDARD_NAME].get('type', '')\\n    clean_vals = df_clean[STANDARD_NAME].dropna()\\n    if declared_type == 'likert':\\n        non_01 = clean_vals[(clean_vals < 0) | (clean_vals > 1)]\\n        if len(non_01) > 0:\\n            errors.append(f\\\"type=likert but clean values out of [0,1]: {sorted(non_01.unique())}\\\")\\n        elif not pd.api.types.is_numeric_dtype(clean_vals):\\n            errors.append(f\\\"type=likert but clean values are not numeric: dtype={clean_vals.dtype}\\\")\\n        else:\\n            print(f\\\"[OK] type=likert, values in [0,1]\\\")\\n    elif declared_type == 'binary':\\n        unexpected = set(clean_vals.unique()) - {0.0, 1.0}\\n        if unexpected:\\n            errors.append(f\\\"type=binary but unexpected clean values: {unexpected}\\\")\\n        else:\\n            print(f\\\"[OK] type=binary, values are 0.0/1.0\\\")\\n    elif declared_type == 'categorical':\\n        if pd.api.types.is_numeric_dtype(clean_vals):\\n            warnings.append(f\\\"type=categorical but clean values are numeric — expected strings\\\")\\n        else:\\n            print(f\\\"[OK] type=categorical, values are strings\\\")\\n\\n# Check 9: codebook_entry values vs mapping keys\\n# Codebook codes that appear in data but are unmapped (excluding known missing codes)\\n# We already have unmapped_vals from Check 2.\\n# Cross-reference with CODEBOOK_VALUES to identify which are documented vs undocumented.\\nif CODEBOOK_VALUES:\\n    codebook_codes = set(str(k) for k in CODEBOOK_VALUES.keys())\\n    # Unmapped values that ARE in the codebook (not just missing codes) = real problem\\n    unmapped_str = set(str(v) for v in unmapped_vals)\\n    undocumented_unmapped = unmapped_str - codebook_codes\\n    documented_unmapped = unmapped_str & codebook_codes\\n    if documented_unmapped:\\n        errors.append(f\\\"Codebook values not mapped (data has them, codebook documents them): {documented_unmapped}\\\")\\n    if undocumented_unmapped:\\n        warnings.append(f\\\"Undocumented codes in data (not in codebook, becoming NaN): {undocumented_unmapped}\\\")\\n    if not documented_unmapped and not undocumented_unmapped:\\n        print(f\\\"[OK] All codebook values are mapped\\\")\\n\\n# --- VERDICT ---\\nprint(\\\"\\\")\\nprint(\\\"=\\\"*60)\\nif errors:\\n    print(\\\"VERDICT: needs_fix\\\")\\n    for e in errors:\\n        print(f\\\"  [ERROR] {e}\\\")\\n    for w in warnings:\\n        print(f\\\"  [WARN]  {w}\\\")\\n    sys.exit(1)\\nelif warnings:\\n    print(\\\"VERDICT: ok (with warnings)\\\")\\n    for w in warnings:\\n        print(f\\\"  [WARN]  {w}\\\")\\nelse:\\n    print(\\\"VERDICT: ok\\\")\\nprint(\\\"=\\\"*\",\n          \"time\": {\n            \"start\": 1773452541389,\n            \"end\": 1773452541389\n          },\n          \"id\": \"prt_cea021892001oxJUN3d2PC6SJc\",\n          \"sessionID\": \"ses_315fe039affen5r12Wgz4YhH4z\",\n          \"messageID\": \"msg_cea021675001edIlzRyqEyRCoL\"\n        },\n        {\n          \"type\": \"step-finish\",\n          \"reason\": \"error\",\n          \"snapshot\": \"0347ad09ad563b25a1b86b59986aeab5d8964853\",\n          \"cost\": 0.003066775,\n          \"tokens\": {\n            \"total\": 22063,\n            \"input\": 1356,\n            \"output\": 6436,\n            \"reasoning\": 0,\n            \"cache\": {\n              \"read\": 14271,\n              \"write\": 0\n            }\n          },\n          \"id\": \"prt_cea023dd10016iMnel6x9aBeg3\",\n          \"sessionID\": \"ses_315fe039affen5r12Wgz4YhH4z\",\n          \"messageID\": \"msg_cea021675001edIlzRyqEyRCoL\"\n        },\n        {\n          \"type\": \"patch\",\n          \"hash\": \"ba6a76f9d8861d23f7282fdf55bef9a7a83899d4\",\n          \"files\": [\n            \"/home/hubcad25/opubliq/repos/survey-cleaner/surveys/eeq_2007/vars/q11.py\",\n            \"/home/hubcad25/opubliq/repos/survey-cleaner/surveys/pipeline.py\"\n          ],\n          \"id\": \"prt_cea023deb0011qv4yngUbX32a7\",\n          \"sessionID\": \"ses_315fe039affen5r12Wgz4YhH4z\",\n          \"messageID\": \"msg_cea021675001edIlzRyqEyRCoL\"\n        }\n      ]\n    }\n  ]\n}\n",
